private JsonNode canonicalize(Object request) {
    JsonNode node = objectMapper.valueToTree(request);
    normalizeDecimals(node);
    return node;
}
private void normalizeDecimals(JsonNode node) {
    if (node.isObject()) {
        JsonNode tokens = node.get("numericTokens");
        if (tokens != null && tokens.isArray()) {
            for (JsonNode token : tokens) {
                JsonNode value = token.get("value");
                if (value != null && value.isTextual()) {
                    ((ObjectNode) token).put("value", canonicalDecimal(value.asText()));
                }
            }
        }
        node.properties().forEach(e -> normalizeDecimals(e.getValue())); // careful with concurrent mod
    } else if (node.isArray()) {
        node.forEach(this::normalizeDecimals);
    }
}
private String canonicalDecimal(String text) {
    try {
        return new BigDecimal(text).stripTrailingZeros().toPlainString();
    } catch (NumberFormatException e) {
        return text;
    }
}
```

